    let day = String(i);

    if (!schedule[day]) {
        schedule[day] = {};
    }

    //  SI ESTÁ DESACTIVADO → respetar
    if (schedule[day].enabled === false) {
        schedule[day] = { enabled: false };
        continue;
    }

    let start = schedule[day].start;
    let end = schedule[day].end;

    //  CASO 1: ambos vacíos → desactivar
    if ((!start || start === "") && (!end || end === "")) {
        schedule[day] = { enabled: true };
        continue;
    }

    //  CASO 2: solo start vacío
    if (!start || start === "") {
        schedule[day].start = "00:00";
    }

    //  CASO 3: solo end vacío
    if (!end || end === "") {
        schedule[day].end = "23:59";
    }

    //  LIMPIAR enabled si estaba activo
    schedule[day] = {
        start: schedule[day].start,
        end: schedule[day].end
    };
}

