// ==========================================================

let data = msg.payload;

// ----------------------------------------------------------
// 1. Obtener duración programada ACTUAL
// Esta es la duración que Python está usando en este momento
// ----------------------------------------------------------

let durationToday = Number(data.duracion_programada);

if (!Number.isFinite(durationToday) || durationToday <= 0) {
    return msg;
}

// ----------------------------------------------------------
// 2. Obtener día actual
// ----------------------------------------------------------

let currentDay = Number(data.day);

if (!Number.isFinite(currentDay) || currentDay < 1) {
    return msg;
}

// ----------------------------------------------------------
// 3. Detectar CAMBIO DE DÍA
// ----------------------------------------------------------

let previousDay = context.get("previous_day");

// Si ya teníamos un día guardado y cambió:
if (previousDay !== undefined && Number(previousDay) !== currentDay) {

    node.warn(
        "CAMBIO DE DÍA → Día " +
        previousDay +
        " → Día " +
        currentDay +
        ". Reiniciando duraciones."
    );

    // ------------------------------------------------------
    // Borrar las duraciones guardadas del día anterior
    // ------------------------------------------------------

    context.set("riego_duraciones", {});

    // ------------------------------------------------------
    // Borrar del mensaje actual los riego_segundos_X
    // anteriores.
    //
    // IMPORTANTE:
    // Esto NO borra nada de Influx.
    // Solo limpia el mensaje/contexto de Node-RED.
    // ------------------------------------------------------

    for (let i = 1; i <= 8; i++) {

        let campoDuracion = "riego_segundos_" + i;

        delete data[campoDuracion];
    }

    // ------------------------------------------------------
    // Reiniciar acumulado del nuevo día
    // ------------------------------------------------------

    data.riego_segundos_total_hoy = 0;
}

// Guardar el día actual para la próxima ejecución
context.set("previous_day", currentDay);


// ----------------------------------------------------------
// 4. Recuperar estado anterior de los puntos
// ----------------------------------------------------------

let previous = context.get("previous_riego_puntos");


// ----------------------------------------------------------
// 5. PRIMER MENSAJE
// ----------------------------------------------------------
// Si Node-RED acaba de arrancar/reiniciar y todavía no tiene
// estado anterior, NO contamos los puntos que ya estén en 1.
//
// Solo inicializamos el estado.
//
// Esto evita registrar falsamente un riego al desplegar
// la Function.
// ----------------------------------------------------------

if (!previous) {

    let inicial = {};

    for (let i = 1; i <= 8; i++) {

        let campo = "riego_punto_" + i;

        inicial[campo] =
            Number(data[campo] || 0);
    }

    context.set(
        "previous_riego_puntos",
        inicial
    );

    // Recuperamos duraciones ya guardadas del día actual
    let duracionesIniciales =
        context.get("riego_duraciones") || {};

    for (let i = 1; i <= 8; i++) {

        let campoDuracion =
            "riego_segundos_" + i;

        if (
            duracionesIniciales[campoDuracion]
            !== undefined
        ) {

            data[campoDuracion] =
                duracionesIniciales[campoDuracion];
        }
    }

    // Calcular total
    let totalInicial = 0;

    for (let i = 1; i <= 8; i++) {

        let campoDuracion =
            "riego_segundos_" + i;

        if (
            data[campoDuracion]
            !== undefined
        ) {

            totalInicial +=
                Number(data[campoDuracion]) || 0;
        }
    }

    data.riego_segundos_total_hoy =
        totalInicial;

    msg.payload = data;

    return msg;
}


// ----------------------------------------------------------
// 6. Recuperar duraciones guardadas
// ----------------------------------------------------------

let duraciones =
    context.get("riego_duraciones") || {};


// ----------------------------------------------------------
// 7. Detectar cambios 0 → 1
// ----------------------------------------------------------

for (let i = 1; i <= 8; i++) {

    let campo =
        "riego_punto_" + i;

    let actual =
        Number(data[campo] || 0);

    let anterior =
        Number(previous[campo] || 0);

    // ------------------------------------------------------
    // AQUÍ ESTÁ LA PARTE IMPORTANTE
    //
    // El punto acaba de pasar:
    //
    // 0 → 1
    //
    // Entonces tomamos duracion_programada AHORA MISMO.
    // ------------------------------------------------------

    if (
        actual === 1 &&
        anterior === 0
    ) {

        let campoDuracion =
            "riego_segundos_" + i;

        data[campoDuracion] =
            durationToday;

        duraciones[campoDuracion] =
            durationToday;

        node.warn(
            "RIEGO " + i +
            " INICIADO → Día " +
            currentDay +
            " → " +
            durationToday +
            " segundos"
        );
    }
}


// ----------------------------------------------------------
// 8. Recuperar duraciones anteriores DEL DÍA ACTUAL
// ----------------------------------------------------------

for (let i = 1; i <= 8; i++) {

    let campoDuracion =
        "riego_segundos_" + i;

    if (
        duraciones[campoDuracion]
        !== undefined
    ) {

        data[campoDuracion] =
            duraciones[campoDuracion];
    }
}


// ----------------------------------------------------------
// 9. Calcular TOTAL DE SEGUNDOS DEL DÍA
// ----------------------------------------------------------

let totalSegundos = 0;

for (let i = 1; i <= 8; i++) {

    let campoDuracion =
        "riego_segundos_" + i;

    if (
        data[campoDuracion]
        !== undefined
    ) {

        totalSegundos +=
            Number(data[campoDuracion]) || 0;
    }
}

data.riego_segundos_total_hoy =
    totalSegundos;


// ----------------------------------------------------------
// 10. Guardar estado actual de los puntos
// ----------------------------------------------------------

let nuevoPrevious = {};

for (let i = 1; i <= 8; i++) {

    let campo =
        "riego_punto_" + i;

    nuevoPrevious[campo] =
        Number(data[campo] || 0);
}

context.set(
    "previous_riego_puntos",
    nuevoPrevious
);


// ----------------------------------------------------------
// 11. Guardar duraciones
// ----------------------------------------------------------

context.set(
    "riego_duraciones",
    duraciones
);


// ----------------------------------------------------------
// 12. Devolver mensaje
// ----------------------------------------------------------

msg.payload = data;

return msg;

